"""Tiny alphabets, long words: exhaustive language check up to length 10."""
import json, random, sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import fuzz

fuzz.WORD_BOUND = 10

def gen_expr(rng, services, depth=0):
    r = rng.random()
    if depth >= 3:
        r = min(r, 0.5)
    if r < 0.08:
        return {'op': 'true'}
    if r < 0.16:
        return {'op': 'false'}
    if r < 0.30:
        return {'op': 'not', 'arg': gen_expr(rng, services, depth + 1)}
    if r < 0.42:
        return {'op': 'and', 'args': [gen_expr(rng, services, depth + 1)
                                      for _ in range(rng.randint(0, 3))]}
    if r < 0.54:
        return {'op': 'or', 'args': [gen_expr(rng, services, depth + 1)
                                     for _ in range(rng.randint(0, 3))]}
    op = rng.choice(['match', 'startswith', 'endswith', 'contains'])
    return {'op': op, 'path': [rng.choice(services)
                               for _ in range(rng.randint(0, 6))]}

def gen_request(rng):
    n = rng.choice([1, 2])
    services = ['p', 'q'][:n]
    rules = []
    for _ in range(rng.randint(0, 3)):
        rules.append({'action': rng.choice(['allow', 'drop']),
                      'when': gen_expr(rng, services)})
    if rng.random() < 0.2:
        rules.append({'action': 'allow', 'when': {'op': 'true'}})
    queries = [[rng.choice(services) for _ in range(rng.randint(0, 10))]
               for _ in range(rng.randint(0, 4))]
    return {'services': services, 'rules': rules, 'queries': queries}

fuzz.gen_request = gen_request
fuzz.gen_expr = gen_expr
if __name__ == '__main__':
    raise SystemExit(fuzz.main())
EOF
